    graph = defaultdict(list)
    for a, b in edges:
        graph[a].append(b)
        graph[b].append(a)

    total_count = 0
    for i in range(2**(N-1)):
        color = ['W'] * (N + 1)
        for j in range(N-1):
            if (i >> j) & 1:
                color[edges[j][0]] = 'B'
                color[edges[j][1]] = 'B'

        valid = True
        for u, v in restrictions:
            path_black = False
            stack = [u]
            visited = set()
            while stack:
                node = stack.pop()
                if node == v:
                    path_black = True
                    break
                visited.add(node)
                for neighbor in graph[node]:
                    if neighbor not in visited:
                        stack.append(neighbor)
            if not path_black:
                valid = False
                break

        if valid:
            total_count += dfs(1, -1, color, graph, restrictions)

    return total_count

